local loader=require("engine.data.loader");local S=require("engine.session");local I=require("engine.interpreter");local E=require("engine.exploration");local director=require("engine.director");local p,f=0,0;local function check(v,m)if v then p=p+1;print("  [PASS] "..m)else f=f+1;print("  [FAIL] "..m)end end;loader.init()
local function load(s,id)E.loadMap(s,assert(loader.getMapIndex(id)))end;local function find(id,name,s)local map=s and s.currentMapData and s.currentMapData.id==id and s.currentMapData or loader.maps[loader.getMapIndex(id)];for _,v in ipairs(map.events or{})do if v.name==name then return v end end end
local function run(s,v)
 local resolved=E.resolvePage(v,s);local ctx={session=s,loader=loader,events={},party=s.party or{},event=resolved};local graph=I.runInteractive(resolved.commands or{},ctx);local walker=director.GraphWalker.new(s,graph);local guard=0
 while walker:getCurrentNode() do
  guard=guard+1;if guard>100 then error("metro Event graph did not terminate") end
  local node=walker:getCurrentNode()
  if node.type=="ACTION" and node.action=="RUN_IMMEDIATE" then I.runImmediate(node.commands or{},ctx);walker:advance()
  elseif node.type=="TEXT" then walker:advance()
  elseif node.type=="CHOICE" then walker:selectChoice(1)
  elseif node.type=="ACTION" and node.action=="START_BATTLE" then return node,resolved
  else walker:advance() end
 end
 return nil,resolved
end
for id=32,36 do local map=loader.maps[loader.getMapIndex(id)];check(map and map.id==id,"metro map "..id.." registered");local t;for _,v in ipairs(map.events or{})do if v.mover then t=v break end end;check(t and t.mover.type=="path","map "..id.." authors path mover");check(t and #t.mover.footprint==9 and #t.mover.ports==3,"map "..id.." authors footprint and ports");check(t and t.mover.visual.models.open and t.mover.visual.models.closed,"map "..id.." authors visual states")end
