local neg=S.GameSession.new(loader);neg:initializeStartingParty();load(neg,35);local vault=find(35,"Faria Lima Vault",neg);local ng=neg.gold;run(neg,vault);check(neg.flags.metro_master_pass~=true and neg.gold==ng,"vault refuses reward without power");load(s,35);vault=find(35,"Faria Lima Vault",s);local bg=s.gold;run(s,vault);check(s.flags.metro_master_pass==true and s.gold==bg+10000,"vault Event grants pass and gold");run(s,vault);check(s.gold==bg+10000,"vault cleared branch prevents duplicate reward");load(s,36);run(s,find(36,"Terminal Access",s));check(s.flags.metro_boss_access==true,"terminal opens after both prerequisites");local boss=find(36,"O Tatuzao",s);local resolved=E.resolvePage(boss,s);check(resolved.commands[1]and resolved.commands[1].cmd=="BATTLE","boss resolves to battle page");local graph=I.runInteractive(resolved.commands,{session=s,loader=loader,events={},party=s.party});local bn;for _,n in pairs(graph.nodes or{})do if n.action=="START_BATTLE"then bn=n break end end;check(bn and bn.troop=="boss_red_dragon","interpreter compiles real boss battle");local bc=resolved.commands[1];check(bc.onVictory and bc.onVictory[1]and bc.onVictory[1].flag=="metro_stratum_solved","boss victory branch wired to completion");I.runImmediate(bc.onVictory,{session=s,loader=loader,events={},party=s.party});check(s.flags.metro_stratum_solved==true,"authored boss victory branch sets completion");run(s,find(36,"Santa Cruz Emergency Corridor",s));check(s.flags.metro_shortcut_unlocked==true and s.currentMapData.id==32,"shortcut Event unlocks and returns to Blue")
